SELECT '6818738b-96ab-4699-9a44-73fa63bd6445'::uuid,'e9aaafb2-4051-4e28-9447-6b30afb6b51a'::uuid,v.nombre,v.nombre_en,v.precio,v.peso,v.subcategoria,NULLIF(v.tamano,''),v.descripcion,v.descripcion_en,false,'unidad',
