CASE WHEN v.n=11 THEN '0076808280739' END,CASE WHEN v.n=11 THEN 'Open Food Facts' END,CASE WHEN v.n=11 THEN 'https://world.openfoodfacts.org/product/0076808280739' END,CASE WHEN v.n=11 THEN 'CC BY-SA' END,CASE WHEN v.n=11 THEN 'house/pantry/2026-10-12/off/11-original.jpg' END,v.n=11
FROM catalog v WHERE NOT EXISTS (SELECT 1 FROM public.store_products p WHERE p.business_id='6818738b-96ab-4699-9a44-73fa63bd6445' AND (lower(p.nombre)=lower(v.nombre) OR lower(p.nombre_en)=lower(v.nombre_en))) RETURNING id)
